layer.css:
[data-ryt="footer"] { background-image: url("{{assets}}/aether_81483842bed9/home-blob-flip.svg"); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="pitch"] { color: var(--ryt-text); border-left: 5px solid rgb(209, 209, 209); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18.4px; font-weight: 400; font-style: italic; line-height: 1.9; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 9.2px; padding-right: 9.2px; padding-bottom: 9.2px; padding-left: 9.2px; transition: all; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-radius: 19.2px; box-shadow: rgba(0, 0, 0, 0.1) 0px 11.2px 36.8px 0px; transition: transform 0.2s cubic-bezier(0.25, 0.8, 0.25, 1), box-shadow 0.2s cubic-bezier(0.25, 0.8, 0.25, 1) }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-text); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: rgb(42, 42, 132); font-family: var(--ryt-font-heading); font-size: 36.8px; font-weight: 500; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(42, 42, 132); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 27.6px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16.56px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: #7f7f7f; font-family: var(--ryt-font-heading); font-size: 12.88px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(142, 142, 142); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); background-color: var(--ryt-surface); border-radius: 19.2px; box-shadow: rgba(0, 0, 0, 0.1) 0px 11.2px 36.8px 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: transform 0.2s cubic-bezier(0.25, 0.8, 0.25, 1), box-shadow 0.2s cubic-bezier(0.25, 0.8, 0.25, 1) }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(42, 42, 132); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 23.92px; font-weight: 500; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(42, 42, 132); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { transform: scale(0.97); box-shadow: rgba(0, 0, 0, 0.2) 0px 0.4rem 2rem }
article[data-ryt="rec-card"]:hover { transform: scale(0.97); box-shadow: rgba(0, 0, 0, 0.2) 0px 0.4rem 2rem }
